async def _fetch_promo_by_code(session: AsyncSession, code: str) -> PromoCode | None:
    from sqlalchemy import func
    result = await session.execute(
        select(PromoCode).where(func.lower(PromoCode.code) == func.lower(code))
    )
    return result.scalar_one_or_none()


def _is_promo_valid(promo: PromoCode) -> bool:
    from datetime import datetime
    from sqlalchemy import UTC
    if promo.expires_at and promo.expires_at < datetime.now(UTC):
        return False
    if promo.max_uses and promo.current_uses >= promo.max_uses:
        return False
    return True"}

